h1,h2,h3{line-height:1.15;margin:0 0 .5em;font-weight:700;letter-spacing:-.01em}
h1{font-size:clamp(2.4rem,6vw,4.5rem);text-transform:uppercase}
h2{font-size:clamp(1.6rem,3.5vw,2.4rem)}
h3{font-size:1.15rem}
.eyebrow{font-size:.75rem;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin:0 0 12px}
.btn{display:inline-block;padding:13px 28px;background:var(--ink);color:#fff;text-decoration:none;font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;border:1px solid var(--ink);transition:.2s}
.btn:hover{background:#fff;color:var(--ink)}
.btn.light{background:#fff;color:var(--ink);border-color:#fff}
.btn.light:hover{background:transparent;color:#fff}
.link{font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;font-weight:600;text-decoration:none;border-bottom:1px solid currentColor;padding-bottom:2px}

.announce{background:var(--accent);color:#fff;text-align:center;font-size:.8rem;letter-spacing:.1em;text-transform:uppercase;padding:9px var(--gutter)}
.announce a{text-decoration:none}
header.site{position:sticky;top:0;z-index:10;background:#fff;border-bottom:1px solid var(--line)}
header.site .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;height:68px}
.logo img{height:34px;width:auto}
nav ul{display:flex;gap:28px;list-style:none;margin:0;padding:0}
nav a,.util a{text-decoration:none;font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;font-weight:600}
nav a:hover,.util a:hover{opacity:.55}
.util{display:flex;gap:20px}
@media(max-width:700px){header.site .wrap{flex-wrap:wrap;height:auto;padding-top:12px;padding-bottom:8px}nav{order:3;width:100%}nav ul{gap:18px;justify-content:space-between}}

.hero{padding:0;background:var(--soft)}
.hero .wrap{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:40px;min-height:560px;padding-top:48px;padding-bottom:48px}
.hero p.lead{font-size:1.15rem;max-width:30em;color:var(--muted)}
.hero .ctas{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin-top:28px}
.hero img{width:100%;aspect-ratio:4/5;object-fit:cover;background:#d9d3c8}
@media(max-width:800px){.hero .wrap{grid-template-columns:1fr;min-height:0}}

.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.tile{background:var(--soft);padding:40px 28px;display:flex;flex-direction:column;align-items:flex-start;gap:10px;min-height:220px;justify-content:flex-end}
.tile h3{font-size:1.5rem;margin:0}
.tile p{margin:0 0 10px;color:var(--muted)}
@media(max-width:800px){.tiles{grid-template-columns:1fr}.tile{min-height:0}}

.products{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.product{border:1px solid var(--line);padding:28px;text-decoration:none;display:flex;flex-direction:column;gap:12px;transition:.2s}
.product:hover{border-color:var(--ink);transform:translateY(-3px)}
.product .swatch{aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-size:.75rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.85)}
.tag{align-self:flex-start;font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;background:var(--soft);padding:4px 10px}
@media(max-width:800px){.products{grid-template-columns:1fr}}

.split{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
.split.rev>:first-child{order:2}
.split img{width:100%;aspect-ratio:4/3;object-fit:cover;background:#cfd8d6}
.split p{color:var(--muted);max-width:34em}
@media(max-width:800px){.split{grid-template-columns:1fr;gap:28px}.split.rev>:first-child{order:0}}
.dark{background:var(--accent);color:#fff}
.dark p,.dark .eyebrow{color:rgba(255,255,255,.75)}
.soft{background:var(--soft)}

.press{display:grid;grid-template-columns:repeat(3,1fr);gap:32px 24px}
.press figure{margin:0;text-align:center}
.press img{width:140px;height:105px;object-fit:contain;margin:0 auto 8px}
.press blockquote{margin:0;color:var(--muted);font-style:italic}
@media(max-width:800px){.press{grid-template-columns:1fr 1fr}}
@media(max-width:480px){.press{grid-template-columns:1fr}}

.ethos ul{padding-left:1.1em;color:var(--muted)}
.ethos li{margin-bottom:12px}
.opp{display:flex;gap:20px;align-items:center;margin-top:24px}
.opp img{width:72px;height:auto}

.posts{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.post{border-top:2px solid var(--ink);padding-top:18px;display:flex;flex-direction:column;gap:10px;align-items:flex-start}
.post .date{font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.post p{margin:0;color:var(--muted)}
@media(max-width:800px){.posts{grid-template-columns:1fr}}
.head-row{display:flex;justify-content:space-between;align-items:baseline;gap:16px;flex-wrap:wrap;margin-bottom:32px}
.head-row h2{margin:0}

.signup{text-align:center}
.signup form{display:flex;gap:0;max-width:480px;margin:24px auto 0}
.signup input{flex:1;min-width:0;padding:13px 16px;border:1px solid var(--ink);border-right:0;font:inherit}
.signup .btn{cursor:pointer;font-family:inherit}

footer{background:#111;color:#cfcfcf;padding:56px 0 32px;font-size:.9rem}
footer a{text-decoration:none}
footer a:hover{color:#fff;text-decoration:underline}
.fcols{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px}
footer h4{color:#fff;font-size:.75rem;letter-spacing:.16em;text-transform:uppercase;margin:0 0 14px}
footer ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.pay{display:flex;flex-wrap:wrap;gap:8px;margin-top:36px;padding-top:24px;border-top:1px solid #333}
.pay img{height:28px;width:auto;background:#fff;border-radius:4px;padding:3px 6px}
.copy{margin-top:20px;font-size:.8rem;color:#888}
@media(max-width:700px){.fcols{grid-template-columns:1fr}}
EOF
